391	  connect(): Promise<void> {
392	    if (this.socket?.readyState === OPEN) return Promise.resolve();
393	    if (this.socket?.readyState === CONNECTING && this.connectPromise !== null) {
394	      return this.connectPromise;
395	    }
396	    this.manuallyDisconnected = false;
397	    this.options.setConnectionStatus(
398	      this.hasConnected ? "reconnecting" : "connecting",
399	    );
400	    this.connectPromise = new Promise<void>((resolve, reject) => {
401	      this.resolveConnect = resolve;
402	      this.rejectConnect = reject;
403	    });
404	    this.openSocket();
405	    return this.connectPromise;
406	  }
