408	  disconnect(): void {
409	    this.manuallyDisconnected = true;
410	    this.disconnectGeneration += 1;
411	    if (this.reconnectTimer !== null) {
412	      clearTimeout(this.reconnectTimer);
413	      this.reconnectTimer = null;
414	    }
415	    const error = new Error("WebSocket transport disconnected");
416	    this.rejectPendingPings(error);
417	    this.rejectConnectionWaiters(error);
418	    this.rejectConnect?.(error);
419	    this.finishConnect();
420	    const socket = this.socket;
421	    this.socket = null;
422	    this.active.clear();
423	    this.desired.clear();
424	    this.discardAssistantStreamFrames();
425	    this.options.deactivateAssistantStreams();
426	    if (socket !== null) {
427	      socket.onopen = null;
428	      socket.onclose = null;
429	      socket.onerror = null;
430	      socket.onmessage = null;
431	      socket.close(1000, "client disconnect");
432	    }
433	    this.options.setConnectionStatus("disconnected");
434	  }
