436	  subscribe(taskId: string, afterSequence: number): void {
437	    const previous = this.desired.get(taskId);
438	    this.desired.set(taskId, Math.max(previous ?? 0, afterSequence));
439	    if (this.isConnected && !this.active.has(taskId)) {
440	      this.send({
441	        type: "subscribe",
442	        task_id: taskId,
443	        after_sequence: Math.max(
444	          this.desired.get(taskId) ?? 0,
445	          this.options.getLastSequence(taskId),
446	        ),
447	      });
448	      this.active.add(taskId);
449	    }
450	  }
