452	  unsubscribe(taskId: string): void {
453	    this.desired.delete(taskId);
454	    this.discardAssistantStreamFrames(taskId);
455	    this.options.deactivateAssistantStreams(taskId);
456	    if (this.isConnected && this.active.has(taskId)) {
457	      this.send({ type: "unsubscribe", task_id: taskId });
458	      this.awaitingUnsubscribe.add(taskId);
459	    }
460	  }
