462	  ping(): Promise<void> {
463	    if (!this.isConnected) {
464	      return Promise.reject(new Error("WebSocket transport is not connected"));
465	    }
466	    const promise = new Promise<void>((resolve, reject) => {
467	      const pending: PendingPing = { resolve, reject, timer: null };
468	      const timeoutMs = this.options.pingTimeoutMs ?? 10_000;
469	      pending.timer = setTimeout(() => {
470	        const index = this.pendingPings.indexOf(pending);
560	        if (attempt.controlError !== null) throw attempt.controlError;
561	        return;
562	      } catch (error) {
563	        const controlError = attempt?.controlError ?? null;
564	        if (this.recoveryAttempt === attempt) this.recoveryAttempt = null;
565	        if (controlError !== null) throw controlError;
