570	          throw error;
571	        }
572	        await this.waitForConnection(disconnectGeneration);
573	      } finally {
574	        if (this.recoveryAttempt === attempt) this.recoveryAttempt = null;
575	      }
576	    }
577	  }
578	
579	  private waitForConnection(disconnectGeneration: number): Promise<void> {
580	    if (disconnectGeneration !== this.disconnectGeneration) {
581	      return Promise.reject(new Error("WebSocket transport disconnected"));
582	    }
583	    if (this.isConnected) return Promise.resolve();
584	    return new Promise<void>((resolve, reject) => {
585	      this.connectionWaiters.push({ resolve, reject });
586	    });
