589	  private replaceSocket(): void {
590	    if (this.reconnectTimer !== null) {
591	      clearTimeout(this.reconnectTimer);
592	      this.reconnectTimer = null;
593	    }
594	    const error = new Error("WebSocket transport replaced for replay recovery");
595	    this.rejectPendingPings(error);
596	    this.rejectConnect?.(error);
597	    this.finishConnect();
598	    const socket = this.socket;
599	    this.socket = null;
600	    this.active.clear();
601	    this.awaitingUnsubscribe.clear();
602	    this.discardAssistantStreamFrames();
603	    this.options.deactivateAssistantStreams();
604	    if (socket !== null) {
605	      socket.onopen = null;
606	      socket.onclose = null;
607	      socket.onerror = null;
608	      socket.onmessage = null;
609	      socket.close(1000, "replay recovery");
610	    }
611	  }
