613	  private openSocket(): void {
614	    const configuredUrl = this.options.url;
615	    const url =
616	      typeof configuredUrl === "function"
617	        ? configuredUrl()
618	        : configuredUrl ?? browserSocketUrl();
619	    const socket = this.options.socketFactory(url);
620	    this.socket = socket;
621	
622	    socket.onopen = () => {
623	      if (this.socket !== socket) return;
624	      this.active.clear();
625	      this.awaitingUnsubscribe.clear();
626	      this.hasConnected = true;
627	      this.options.setConnectionStatus("connected");
628	      this.flushSubscriptions();
629	      this.resolveConnectionWaiters();
630	      this.resolveConnect?.();
631	      this.finishConnect();
632	    };
633	    socket.onmessage = (event) => {
634	      if (this.socket !== socket) return;
635	      this.handleFrame(parseFrame(event.data));
636	    };
637	    socket.onerror = () => {
638	      if (this.socket !== socket) return;
639	      this.options.setConnectionStatus(
640	        this.manuallyDisconnected ? "disconnected" : "reconnecting",
641	      );
642	    };
643	    socket.onclose = () => {
644	      if (this.socket !== socket) return;
645	      this.socket = null;
646	      this.active.clear();
647	      this.awaitingUnsubscribe.clear();
648	      this.discardAssistantStreamFrames();
649	      this.options.deactivateAssistantStreams();
650	      const error = new Error("WebSocket transport closed");
651	      this.rejectPendingPings(error);
652	      this.rejectConnect?.(error);
653	      this.finishConnect();
654	      if (this.manuallyDisconnected) {
655	        this.options.setConnectionStatus("disconnected");
656	        return;
657	      }
658	      this.options.setConnectionStatus("reconnecting");
659	      this.scheduleReconnect();
660	    };
661	  }
