663	  private flushSubscriptions(): void {
664	    for (const taskId of this.desired.keys()) {
665	      this.send({
666	        type: "subscribe",
667	        task_id: taskId,
668	        after_sequence: Math.max(
669	          this.desired.get(taskId) ?? 0,
670	          this.options.getLastSequence(taskId),
671	        ),
672	      });
673	      this.active.add(taskId);
674	    }
