677	  private handleFrame(frame: unknown): void {
678	    if (isControlFrame(frame)) {
679	      if (frame.type === "pong") {
680	        const pending = this.pendingPings.shift();
681	        if (pending?.timer !== null && pending?.timer !== undefined) {
682	          clearTimeout(pending.timer);
683	        }
684	        pending?.resolve();
685	      } else {
686	        if (
687	          frame.task_id !== undefined &&
688	          frame.task_id === this.recoveryAttempt?.taskId
689	        ) {
690	          this.recoveryAttempt.controlError = new Error(
691	            `${frame.code}: ${frame.message}`,
692	          );
693	        }
694	        this.options.onControlError?.(frame);
695	      }
696	      return;
697	    }
698	    if (isAssistantStreamFrame(frame)) {
699	      if (!this.active.has(frame.task_id)) return;
700	      this.queueAssistantStreamFrame(frame);
701	      return;
702	    }
703	    const envelope = normalizeEventEnvelope(frame);
704	    if (envelope === null) return;
705	    if (!this.active.has(envelope.task_id)) return;
706	    this.confirmQueuedAssistantStreamFrames(envelope);
707	    if (isAssistantStreamBoundary(envelope) && envelope.run_id !== null) {
708	      this.discardAssistantStreamFrames(envelope.task_id, envelope.run_id);
709	    }
710	    const gap = this.options.applyEvent(envelope);
711	    this.reconcileSubscription(envelope.task_id);
712	    if (gap !== null && gap !== undefined) {
713	      if (this.desired.has(envelope.task_id)) {
714	        this.recoverSequenceGap(envelope.task_id);
715	      }
716	    } else {
717	      this.gapRecoveryCursors.delete(envelope.task_id);
718	    }
719	  }
