721	  /**
722	   * When the reducer rejected a durable envelope because its sequence is
723	   * not contiguous with the last applied sequence (a frame at N was
724	   * dropped or rejected), request a replay from the last applied
725	   * sequence. The server replays contiguously from ``after_sequence``, so
726	   * the missing frame is re-sent and the gap heals. Bounded to one
727	   * recovery per cursor position to avoid loops on permanent gaps.
728	   */
729	  private recoverSequenceGap(taskId: string): void {
730	    if (this.gapRecoveryCursors.has(taskId)) return;
731	    const afterSequence = this.options.getLastSequence(taskId);
732	    this.gapRecoveryCursors.set(taskId, afterSequence);
733	    void this.recoverSubscription(taskId, afterSequence).catch(() => undefined);
734	  }
