738	   * run reached a terminal state). Kept subscriptions otherwise accumulate
739	   * for the whole session and are resubscribed on every reconnect.
740	   */
741	  private reconcileSubscription(taskId: string): void {
742	    if (this.options.shouldSubscribe?.(taskId) ?? true) return;
743	    if (!this.desired.has(taskId)) return;
744	    this.desired.delete(taskId);
