  7	export function useAgentStream(): AgentEventTransport {
  8	  const transport = useMemo(
  9	    () =>
 10	      new AgentEventTransport({
 11	        socketFactory: (url) => new WebSocket(url),
 12	        getLastSequence: (taskId) =>
 13	          useAgentStore.getState().tasksById[taskId]?.lastSequence ?? 0,
 14	        applyEvent: (event) => useAgentStore.getState().applyEvent(event),
 15	        applyAssistantStreamFrames: (frames) =>
 16	          useAgentStore.getState().applyAssistantStreamFrames(frames),
 17	        deactivateAssistantStreams: (taskId) =>
 18	          useAgentStore.getState().deactivateAssistantStreams(taskId),
 19	        setConnectionStatus: (status) =>
 20	          useAgentStore.getState().setConnectionStatus(status),
 21	        shouldSubscribe: (taskId) =>
 22	          useAgentStore.getState().activeItems.includes(taskId),
 23	        onControlError: (frame) => {
 24	          // Recovery-path errors (task_not_found during resubscribe) are
 25	          // already surfaced via transport internals; only surface generic
 26	          // protocol/internal errors here so users see server-side issues.
 27	          if (frame.code === "task_not_found") return;
 28	          toast.error(`WebSocket 错误: ${frame.code}`, {
 29	            description: frame.message,
 30	          });
 31	        },
 32	      }),
 33	    [],
 34	  );
 35	
 36	  useEffect(() => () => transport.disconnect(), [transport]);
 37	
 38	  return transport;
 39	}

