 41	export function reduceRuntimeEvent(
 42	  state: AgentRuntimeData,
 43	  envelope: EventEnvelope,
 44	): AgentRuntimeData {
 45	  const current = state.tasksById[envelope.task_id];
 46	  if (current === undefined || envelope.sequence <= current.lastSequence) {
 47	    return state;
 48	  }
 49	  if (envelope.sequence > current.lastSequence + 1) {
 50	    // A frame at N was dropped or rejected before this one (e.g. unknown
 51	    // type, schema drift, or a transport-level reject). Never advance the
 52	    // cursor past the gap: a missed user_input_required would otherwise be
 53	    // permanently unrecoverable. Record a recoverable gap marker and leave
 54	    // the cursor at the last applied sequence so the transport can replay
 55	    // from there. The event payload is NOT reduced.
 56	    return {
 57	      ...state,
 58	      tasksById: {
 59	        ...state.tasksById,
 60	        [envelope.task_id]: {
 61	          ...current,
 62	          sequenceGap: {
 63	            expected: current.lastSequence + 1,
 64	            received: envelope.sequence,
 65	          },
 66	        },
 67	      },
 68	    };
 69	  }
 70	
 71	  const payload = envelope.payload;
 72	  let task = current;
 73	
