295	  >,
296	): TaskProjection {
297	  const runId = envelope.run_id;
298	  if (runId === null) return task;
299	  const status: RunStatus =
300	    payload.type === "run_started"
301	      ? "running"
302	      : payload.type === "run_finalizing"
303	        ? "finalizing"
