309	      ...run,
310	      status,
311	      updatedAt: envelope.timestamp,
312	      startedAt:
313	        payload.type === "run_started"
314	          ? (run.startedAt ?? envelope.timestamp)
315	          : run.startedAt,
316	    }),
317	    status,
318	    envelope.timestamp,
319	  );
320	  next = {
321	    ...next,
322	    summary: { ...next.summary, status, active_run_id: runId },
323	  };
324	  if (payload.type === "run_cancel_requested") {
325	    // A cancelled run is no longer awaiting user input: clear its prompt so
326	    // the blocking dialog does not stay open (or race) while the
327	    // cancellation settles.
328	    if (next.pendingUserInput?.runId === runId) {
329	      next = { ...next, pendingUserInput: null };
330	    }
331	    next = deactivateRunAssistantStream(next, runId);
332	    next = deactivateRunStreamingItems(next, runId);
333	  }
334	  if (payload.type === "run_finalizing") {
335	    next = deactivateRunAssistantStream(next, runId);
336	    next = deactivateRunStreamingItems(next, runId);
337	  }
338	  return next;
339	}
