   296	  private async replayTaskEvents(
   297	    taskId: string,
   298	    targetSequence: number,
   299	  ): Promise<void> {
   300	    let afterSequence =
   301	      useAgentStore.getState().tasksById[taskId]?.lastSequence ?? 0;
   302	    if (targetSequence <= afterSequence) return;
   303	    for (;;) {
   304	      const events = await this.api.fetchEvents(taskId, {
   305	        afterSequence,
   306	        limit: EVENT_REPLAY_PAGE_SIZE,
   307	      });
   308	      if (events.length === 0) {
   309	        const currentSequence =
   310	          useAgentStore.getState().tasksById[taskId]?.lastSequence ?? 0;
   311	        if (currentSequence < targetSequence) {
   312	          throw new Error("Task event replay is incomplete");
   313	        }
   314	        return;
   315	      }
   316	      let nextSequence = afterSequence;
   317	      for (const event of events) {
   318	        useAgentStore.getState().applyEvent(event);
   319	        nextSequence = Math.max(nextSequence, event.sequence);
   320	      }
   321	      const currentSequence =
   322	        useAgentStore.getState().tasksById[taskId]?.lastSequence ?? 0;
   323	      if (currentSequence >= targetSequence) {
   324	        return;
   325	      }
   326	      if (nextSequence <= afterSequence) {
   327	        throw new Error("Task event replay did not advance");
   328	      }
   329	      if (events.length < EVENT_REPLAY_PAGE_SIZE) {
   330	        throw new Error("Task event replay is incomplete");
   331	      }
   332	      afterSequence = nextSequence;
   333	    }
   334	  }
