110	export function mergeTaskPage(
111	  state: AgentRuntimeData,
112	  page: TaskPage,
113	  append: boolean,
114	  preserveTaskIds?: ReadonlySet<string>,
115	): AgentRuntimeData {
116	  const tasksById = { ...state.tasksById };
117	  for (const item of [...page.active_items, ...page.items]) {
118	    tasksById[item.task_id] = mergeSummary(tasksById[item.task_id], item);
119	  }
120	
121	  const pageActive = page.active_items
122	    .map((item) => item.task_id)
123	    .filter((taskId) => isActiveStatus(tasksById[taskId].summary.status));
124	  const preservedActive = state.activeItems.filter(
125	    (taskId) =>
126	      !pageActive.includes(taskId) &&
127	      tasksById[taskId] !== undefined &&
128	      isActiveStatus(tasksById[taskId].summary.status),
129	  );
130	  const activeItems = [...new Set([...pageActive, ...preservedActive])].sort(
131	    (left, right) => compareTaskIds(tasksById, left, right),
132	  );
133	
134	  const incomingHistory = [...page.active_items, ...page.items]
135	    .map((item) => item.task_id)
136	    .filter((taskId) => !isActiveStatus(tasksById[taskId].summary.status));
137	  const preservedHistory = append
138	    ? []
139	    : state.taskOrder.filter((taskId) => preserveTaskIds?.has(taskId));
140	  const history = append
141	    ? [...state.taskOrder, ...incomingHistory]
142	    : [...preservedHistory, ...incomingHistory];
143	  const taskOrder = [...new Set(history)]
144	    .filter((taskId) => !activeItems.includes(taskId))
145	    .sort((left, right) => compareTaskIds(tasksById, left, right));
146	
147	  return {
148	    ...state,
149	    tasksById,
150	    activeItems,
151	    taskOrder,
152	    nextCursor: page.next_cursor,
153	  };
154	}
