341	export function hydrateTaskSnapshot(
342	  state: AgentRuntimeData,
343	  snapshot: TaskSnapshot,
344	): AgentRuntimeData {
345	  const existing = state.tasksById[snapshot.task.task_id];
346	  if (
347	    existing !== undefined &&
348	    snapshot.task.latest_sequence < existing.lastSequence
349	  ) {
350	    return state;
351	  }
352	  const base = existing ?? createTaskProjection(snapshot.task);
353	  const runs = snapshot.runs.map(projectRun);
354	  const subagents = (snapshot.subagents ?? []).map(projectSubagent);
355	  const pendingRun =
356	    base.pendingUserInput === null
357	      ? undefined
358	      : runs.find((run) => run.runId === base.pendingUserInput?.runId);
359	  const snapshotMessages = snapshot.messages.map(projectMessage);
360	  const durableAssistantRunIds = new Set(
361	    snapshotMessages
362	      .filter(
363	        (message): message is ProjectedMessage & { runId: string } =>
364	          message.role === "assistant" &&
365	          message.ordinal !== null &&
366	          message.runId !== null,
367	      )
368	      .map((message) => message.runId),
369	  );
370	  const assistantStreamsByRunId = Object.fromEntries(
371	    Object.entries(base.assistantStreamsByRunId).filter(
372	      ([runId]) => !durableAssistantRunIds.has(runId),
373	    ),
374	  );
375	  const snapshotRunIds = new Set(runs.map((run) => run.runId));
376	  const runOrder = [
377	    ...runs.map((run) => run.runId),
378	    ...base.runOrder.filter((runId) => !snapshotRunIds.has(runId)),
379	  ];
380	  const runsById = {
381	    ...base.runsById,
382	    ...Object.fromEntries(runs.map((run) => [run.runId, run])),
383	  };
384	  const snapshotSubagentIds = new Set(
385	    subagents.map((subagent) => subagent.subagentId),
386	  );
387	  const subagentOrder = [
388	    ...subagents.map((subagent) => subagent.subagentId),
389	    ...base.subagentOrder.filter(
390	      (subagentId) => !snapshotSubagentIds.has(subagentId),
391	    ),
392	  ];
393	  const subagentsById = {
394	    ...base.subagentsById,
395	    ...Object.fromEntries(
396	      subagents.map((subagent) => [
397	        subagent.subagentId,
398	        {
399	          ...subagent,
400	          warnings:
401	            subagent.warnings.length > 0
402	              ? subagent.warnings
403	              : (base.subagentsById[subagent.subagentId]?.warnings ?? []),
404	        },
405	      ]),
406	    ),
407	  };
408	  const task: TaskProjection = mergeMessagesIntoItems({
409	    ...base,
410	    summary: { ...snapshot.task, databases: [...snapshot.task.databases] },
411	    runsById,
412	    runOrder,
413	    subagentsById,
414	    subagentOrder,
415	    messages: mergeSnapshotMessages(base, snapshotMessages),
416	    assistantStreamsByRunId,
417	    currentPublicationId:
418	      snapshot.current_publication_id === undefined
419	        ? base.currentPublicationId
420	        : snapshot.current_publication_id,
421	    publications:
422	      snapshot.publications === undefined
423	        ? base.publications
424	        : [...snapshot.publications],
425	    pendingUserInput:
426	      base.pendingUserInput !== null &&
427	      snapshot.task.active_run_id === base.pendingUserInput.runId &&
428	      pendingRun?.status === "awaiting_user_input"
429	        ? base.pendingUserInput
430	        : null,
431	    olderMessagesCursor:
432	      existing?.hydration === "snapshot" &&
433	      snapshotConnectsToExistingHistory(base, snapshotMessages)
434	        ? base.olderMessagesCursor
435	        : snapshot.older_messages_cursor,
436	    lastSequence: snapshot.task.latest_sequence,
437	    // A snapshot is authoritative: its latest_sequence covers any earlier
438	    // event-window gap, so the recoverable gap marker is healed.
439	    sequenceGap: null,
440	    hydration: "snapshot",
441	  });
442	  const classification = updateClassification(state, task);
443	  return {
444	    ...state,
445	    tasksById: { ...state.tasksById, [snapshot.task.task_id]: task },
446	    ...classification,
447	  };
448	}
