342	  task: TaskProjection,
343	  envelope: EventEnvelope,
344	  payload: Extract<
345	    EventPayload,
346	    | { type: "run_completed" }
347	    | { type: "run_failed" }
348	    | { type: "run_cancelled" }
349	    | { type: "run_interrupted" }
350	  >,
351	): TaskProjection {
352	  const runId = envelope.run_id;
353	  if (runId === null) return task;
354	  const status = terminalStatus(payload.type);
355	  if (status === null) return task;
356	  const error =
357	    payload.type === "run_failed"
358	      ? payload.error
359	      : payload.type === "run_interrupted"
360	        ? payload.reason
361	        : payload.type === "run_cancelled"
362	          ? payload.reason
363	          : null;
364	  let next = upsertRun(
365	    task,
366	    runId,
367	    (run) => ({
368	      ...run,
369	      status,
370	      updatedAt: envelope.timestamp,
371	      finishedAt: envelope.timestamp,
372	      error,
373	      summary: summaryForTerminalPayload(payload, status),
374	    }),
375	    status,
376	    envelope.timestamp,
377	  );
378	  if (next.summary.active_run_id === runId) {
379	    next = {
380	      ...next,
381	      summary: { ...next.summary, status, active_run_id: null },
382	    };
383	  }
384	  if (next.pendingUserInput?.runId === runId) {
385	    next = { ...next, pendingUserInput: null };
386	  }
387	  if (payload.type !== "run_completed") {
388	    next = terminalizeRunningFixtureStages(
389	      next,
390	      payload.type === "run_failed" ? "failed" : "cancelled",
391	      envelope.timestamp,
392	      error,
393	    );
394	  }
395	  next = deactivateRunAssistantStream(next, runId);
396	  next = deactivateRunStreamingItems(next, runId);
397	  return next;
