400	export function applyPublicationCreatedEvent(
401	  task: TaskProjection,
402	  envelope: EventEnvelope,
403	  payload: Extract<EventPayload, { type: "publication_created" }>,
404	): TaskProjection {
405	  // Mirror the backend reducer (raise, don't skip): publication events
406	  // require an envelope run_id and the payload run_id must match it. A
407	  // malformed event must not be silently consumed — skipping would advance
408	  // lastSequence and make it unreplayable on reconnect. A re-delivered
409	  // publication_id is a no-op so duplicate entries never accumulate.
410	  if (envelope.run_id === null) {
411	    throw new Error("publication events require run_id");
412	  }
413	  if (payload.run_id !== envelope.run_id) {
414	    throw new Error("payload run_id must match envelope run_id");
415	  }
416	  if (
417	    task.publications.some(
418	      (publication) => publication.publication_id === payload.publication_id,
419	    )
420	  ) {
421	    return task;
422	  }
423	  const previous = task.currentPublicationId;
424	  const publication: PublicationSummary = {
425	    publication_id: payload.publication_id,
426	    manifest_sha256: payload.manifest_sha256,
427	    supersedes_publication_id: payload.supersedes_publication_id ?? previous,
428	    published_at: payload.published_at,
429	  };
430	  return {
431	    ...task,
432	    currentPublicationId: payload.publication_id,
433	    publications: [...task.publications, publication],
434	  };
435	}
